  952| static OFF
  953| md_skip_unicode_whitespace(const CHAR* label, OFF off, SZ size)
  954| {
  955|     SZ char_size;
  956|     unsigned codepoint;
  957| 
  958|     while(off < size) {
  959|         codepoint = md_decode_unicode(label, off, size, &char_size);
  960|         if(!ISUNICODEWHITESPACE_(codepoint)  &&  !ISNEWLINE_(label[off]))
  961|             break;
  962|         off += char_size;
  963|     }
  964| 
  965|     return off;
  966| }
