 1243| static int
 1244| md_is_hex_entity_contents(MD_CTX* ctx, const CHAR* text, OFF beg, OFF max_end, OFF* p_end)
 1245| {
 1246|     OFF off = beg;
 1247|     MD_UNUSED(ctx);
 1248| 
 1249|     while(off < max_end  &&  ISXDIGIT_(text[off])  &&  off - beg <= 8)
 1250|         off++;
 1251| 
 1252|     if(1 <= off - beg  &&  off - beg <= 6) {
 1253|         *p_end = off;
 1254|         return TRUE;
 1255|     } else {
 1256|         return FALSE;
 1257|     }
 1258| }
