 1260| static int
 1261| md_is_dec_entity_contents(MD_CTX* ctx, const CHAR* text, OFF beg, OFF max_end, OFF* p_end)
 1262| {
 1263|     OFF off = beg;
 1264|     MD_UNUSED(ctx);
 1265| 
 1266|     while(off < max_end  &&  ISDIGIT_(text[off])  &&  off - beg <= 8)
 1267|         off++;
 1268| 
 1269|     if(1 <= off - beg  &&  off - beg <= 7) {
 1270|         *p_end = off;
 1271|         return TRUE;
 1272|     } else {
 1273|         return FALSE;
 1274|     }
 1275| }
