 3410|         if(next_index >= 0) {
 3411|             next_opener = &ctx->marks[next_index];
 3412|             next_closer = &ctx->marks[next_opener->next];
 3413|         } else {
 3414|             next_opener = NULL;
 3415|             next_closer = NULL;
 3416|         }
