 3439|             next_opener->ch == '[' &&
 3440|             (next_opener->beg == opener->beg - 1) &&
 3441|             (next_opener->end - next_opener->beg == 1) &&
 3442|             next_closer != NULL &&                      /* double ']' closer */
 3443|             next_closer->ch == ']' &&
 3444|             (next_closer->beg == closer->beg + 1) &&
