 4121| /* Render the output, accordingly to the analyzed ctx->marks. */
 4122| static int
 4123| md_process_inlines(MD_CTX* ctx, const MD_LINE* lines, int n_lines)
 4124| {
 4125|     MD_TEXTTYPE text_type;
 4126|     const MD_LINE* line = lines;
 4127|     MD_MARK* prev_mark = NULL;
 4128|     MD_MARK* mark;
 4129|     OFF off = lines[0].beg;
 4130|     OFF end = lines[n_lines-1].end;
 4131|     int enforce_hardbreak = 0;
 4132|     int ret = 0;
 4133| 
 4134|     /* Find first resolved mark. Note there is always at least one resolved
 4135|      * mark,  the dummy last one after the end of the latest line we actually
 4136|      * never really reach. This saves us of a lot of special checks and cases
 4137|      * in this function. */
 4138|     mark = ctx->marks;
 4139|     while(!(mark->flags & MD_MARK_RESOLVED))
 4140|         mark++;
 4141| 
 4142|     text_type = MD_TEXT_NORMAL;
 4143| 
 4144|     while(1) {
 4145|         /* Process the text up to the next mark or end-of-line. */
 4146|         OFF tmp = (line->end < mark->beg ? line->end : mark->beg);
 4147|         if(tmp > off) {
 4148|             MD_TEXT(text_type, STR(off), tmp - off);
 4149|             off = tmp;
 4150|         }
 4151| 
 4152|         /* If reached the mark, process it and move to next one. */
 4153|         if(off >= mark->beg) {
 4154|             switch(mark->ch) {
 4155|                 case '\\':      /* Backslash escape. */
 4156|                     if(ISNEWLINE(mark->beg+1))
 4157|                         enforce_hardbreak = 1;
 4158|                     else
 4159|                         MD_TEXT(text_type, STR(mark->beg+1), 1);
 4160|                     break;
 4161| 
 4162|                 case ' ':       /* Non-trivial space. */
 4163|                     MD_TEXT(text_type, _T(" "), 1);
 4164|                     break;
 4165| 
 4166|                 case '`':       /* Code span. */
 4167|                     if(mark->flags & MD_MARK_OPENER) {
 4168|                         MD_ENTER_SPAN(MD_SPAN_CODE, NULL);
 4169|                         text_type = MD_TEXT_CODE;
 4170|                     } else {
 4171|                         MD_LEAVE_SPAN(MD_SPAN_CODE, NULL);
 4172|                         text_type = MD_TEXT_NORMAL;
 4173|                     }
 4174|                     break;
 4175| 
 4176|                 case '_':       /* Underline (or emphasis if we fall through). */
 4177|                     if(ctx->parser.flags & MD_FLAG_UNDERLINE) {
 4178|                         if(mark->flags & MD_MARK_OPENER) {
 4179|                             while(off < mark->end) {
 4180|                                 MD_ENTER_SPAN(MD_SPAN_U, NULL);
 4181|                                 off++;
 4182|                             }
 4183|                         } else {
 4184|                             while(off < mark->end) {
 4185|                                 MD_LEAVE_SPAN(MD_SPAN_U, NULL);
 4186|                                 off++;
 4187|                             }
 4188|                         }
 4189|                         break;
 4190|                     }
 4191|                     MD_FALLTHROUGH();
 4192| 
 4193|                 case '*':       /* Emphasis, strong emphasis. */
 4194|                     if(mark->flags & MD_MARK_OPENER) {
 4195|                         if((mark->end - off) % 2) {
 4196|                             MD_ENTER_SPAN(MD_SPAN_EM, NULL);
 4197|                             off++;
 4198|                         }
 4199|                         while(off + 1 < mark->end) {
 4200|                             MD_ENTER_SPAN(MD_SPAN_STRONG, NULL);
 4201|                             off += 2;
 4202|                         }
 4203|                     } else {
 4204|                         while(off + 1 < mark->end) {
 4205|                             MD_LEAVE_SPAN(MD_SPAN_STRONG, NULL);
 4206|                             off += 2;
 4207|                         }
 4208|                         if((mark->end - off) % 2) {
 4209|                             MD_LEAVE_SPAN(MD_SPAN_EM, NULL);
 4210|                             off++;
 4211|                         }
 4212|                     }
 4213|                     break;
 4214| 
 4215|                 case '~':
 4216|                     if(mark->flags & MD_MARK_OPENER)
 4217|                         MD_ENTER_SPAN(MD_SPAN_DEL, NULL);
 4218|                     else
 4219|                         MD_LEAVE_SPAN(MD_SPAN_DEL, NULL);
 4220|                     break;
 4221| 
 4222|                 case '$':
 4223|                     if(mark->flags & MD_MARK_OPENER) {
 4224|                         MD_ENTER_SPAN((mark->end - off) % 2 ? MD_SPAN_LATEXMATH : MD_SPAN_LATEXMATH_DISPLAY, NULL);
 4225|                         text_type = MD_TEXT_LATEXMATH;
 4226|                     } else {
 4227|                         MD_LEAVE_SPAN((mark->end - off) % 2 ? MD_SPAN_LATEXMATH : MD_SPAN_LATEXMATH_DISPLAY, NULL);
 4228|                         text_type = MD_TEXT_NORMAL;
 4229|                     }
 4230|                     break;
 4231| 
 4232|                 case '[':       /* Link, wiki link, image. */
 4233|                 case '!':
 4234|                 case ']':
 4235|                 {
 4236|                     const MD_MARK* opener = (mark->ch != ']' ? mark : &ctx->marks[mark->prev]);
 4237|                     const MD_MARK* closer = &ctx->marks[opener->next];
 4238|                     const MD_MARK* dest_mark;
 4239|                     const MD_MARK* title_mark;
 4240| 
 4241|                     if ((opener->ch == '[' && closer->ch == ']') &&
 4242|                         opener->end - opener->beg >= 2 &&
 4243|                         closer->end - closer->beg >= 2)
 4244|                     {
 4245|                         int has_label = (opener->end - opener->beg > 2);
 4246|                         SZ target_sz;
 4247| 
 4248|                         if(has_label)
 4249|                             target_sz = opener->end - (opener->beg+2);
 4250|                         else
 4251|                             target_sz = closer->beg - opener->end;
 4252| 
 4253|                         MD_CHECK(md_enter_leave_span_wikilink(ctx, (mark->ch != ']'),
 4254|                                  has_label ? STR(opener->beg+2) : STR(opener->end),
 4255|                                  target_sz));
 4256| 
 4257|                         break;
 4258|                     }
 4259| 
 4260|                     dest_mark = opener+1;
 4261|                     MD_ASSERT(dest_mark->ch == 'D');
 4262|                     title_mark = opener+2;
 4263|                     MD_ASSERT(title_mark->ch == 'D');
 4264| 
 4265|                     MD_CHECK(md_enter_leave_span_a(ctx, (mark->ch != ']'),
 4266|                                 (opener->ch == '!' ? MD_SPAN_IMG : MD_SPAN_A),
 4267|                                 STR(dest_mark->beg), dest_mark->end - dest_mark->beg, FALSE,
 4268|                                 md_mark_get_ptr(ctx, (int)(title_mark - ctx->marks)),
 4269| 								title_mark->prev));
 4270| 
 4271|                     /* link/image closer may span multiple lines. */
 4272|                     if(mark->ch == ']') {
 4273|                         while(mark->end > line->end)
 4274|                             line++;
 4275|                     }
 4276| 
 4277|                     break;
 4278|                 }
 4279| 
 4280|                 case '<':
 4281|                 case '>':       /* Autolink or raw HTML. */
 4282|                     if(!(mark->flags & MD_MARK_AUTOLINK)) {
 4283|                         /* Raw HTML. */
 4284|                         if(mark->flags & MD_MARK_OPENER)
 4285|                             text_type = MD_TEXT_HTML;
 4286|                         else
 4287|                             text_type = MD_TEXT_NORMAL;
 4288|                         break;
 4289|                     }
 4290|                     /* Pass through, if auto-link. */
 4291|                     MD_FALLTHROUGH();
 4292| 
 4293|                 case '@':       /* Permissive e-mail autolink. */
 4294|                 case ':':       /* Permissive URL autolink. */
 4295|                 case '.':       /* Permissive WWW autolink. */
 4296|                 {
 4297|                     MD_MARK* opener = ((mark->flags & MD_MARK_OPENER) ? mark : &ctx->marks[mark->prev]);
 4298|                     MD_MARK* closer = &ctx->marks[opener->next];
 4299|                     const CHAR* dest = STR(opener->end);
 4300|                     SZ dest_size = closer->beg - opener->end;
 4301| 
 4302|                     /* For permissive auto-links we do not know closer mark
 4303|                      * position at the time of md_collect_marks(), therefore
 4304|                      * it can be out-of-order in ctx->marks[].
 4305|                      *
 4306|                      * With this flag, we make sure that we output the closer
 4307|                      * only if we processed the opener. */
 4308|                     if(mark->flags & MD_MARK_OPENER)
 4309|                         closer->flags |= MD_MARK_VALIDPERMISSIVEAUTOLINK;
 4310| 
 4311|                     if(opener->ch == '@' || opener->ch == '.') {
 4312|                         dest_size += 7;
 4313|                         MD_TEMP_BUFFER(dest_size * sizeof(CHAR));
 4314|                         memcpy(ctx->buffer,
 4315|                                 (opener->ch == '@' ? _T("mailto:") : _T("http://")),
 4316|                                 7 * sizeof(CHAR));
 4317|                         memcpy(ctx->buffer + 7, dest, (dest_size-7) * sizeof(CHAR));
 4318|                         dest = ctx->buffer;
 4319|                     }
 4320| 
 4321|                     if(closer->flags & MD_MARK_VALIDPERMISSIVEAUTOLINK)
 4322|                         MD_CHECK(md_enter_leave_span_a(ctx, (mark->flags & MD_MARK_OPENER),
 4323|                                     MD_SPAN_A, dest, dest_size, TRUE, NULL, 0));
 4324|                     break;
 4325|                 }
 4326| 
 4327|                 case '&':       /* Entity. */
 4328|                     MD_TEXT(MD_TEXT_ENTITY, STR(mark->beg), mark->end - mark->beg);
 4329|                     break;
 4330| 
 4331|                 case '\0':
 4332|                     MD_TEXT(MD_TEXT_NULLCHAR, _T(""), 1);
 4333|                     break;
 4334| 
 4335|                 case 127:
 4336|                     goto abort;
 4337|             }
 4338| 
 4339|             off = mark->end;
 4340| 
 4341|             /* Move to next resolved mark. */
 4342|             prev_mark = mark;
 4343|             mark++;
 4344|             while(!(mark->flags & MD_MARK_RESOLVED)  ||  mark->beg < off)
 4345|                 mark++;
 4346|         }
 4347| 
 4348|         /* If reached end of line, move to next one. */
 4349|         if(off >= line->end) {
 4350|             /* If it is the last line, we are done. */
 4351|             if(off >= end)
 4352|                 break;
 4353| 
 4354|             if(text_type == MD_TEXT_CODE || text_type == MD_TEXT_LATEXMATH) {
 4355|                 OFF tmp;
 4356| 
 4357|                 MD_ASSERT(prev_mark != NULL);
 4358|                 MD_ASSERT(ISANYOF2_(prev_mark->ch, '`', '$')  &&  (prev_mark->flags & MD_MARK_OPENER));
 4359|                 MD_ASSERT(ISANYOF2_(mark->ch, '`', '$')  &&  (mark->flags & MD_MARK_CLOSER));
 4360| 
 4361|                 /* Inside a code span, trailing line whitespace has to be
 4362|                  * outputted. */
 4363|                 tmp = off;
 4364|                 while(off < ctx->size  &&  ISBLANK(off))
 4365|                     off++;
 4366|                 if(off > tmp)
 4367|                     MD_TEXT(text_type, STR(tmp), off-tmp);
 4368| 
 4369|                 /* and new lines are transformed into single spaces. */
 4370|                 if(prev_mark->end < off  &&  off < mark->beg)
 4371|                     MD_TEXT(text_type, _T(" "), 1);
 4372|             } else if(text_type == MD_TEXT_HTML) {
 4373|                 /* Inside raw HTML, we output the new line verbatim, including
 4374|                  * any trailing spaces. */
 4375|                 OFF tmp = off;
 4376| 
 4377|                 while(tmp < end  &&  ISBLANK(tmp))
 4378|                     tmp++;
 4379|                 if(tmp > off)
 4380|                     MD_TEXT(MD_TEXT_HTML, STR(off), tmp - off);
 4381|                 MD_TEXT(MD_TEXT_HTML, _T("\n"), 1);
 4382|             } else {
 4383|                 /* Output soft or hard line break. */
 4384|                 MD_TEXTTYPE break_type = MD_TEXT_SOFTBR;
 4385| 
 4386|                 if(text_type == MD_TEXT_NORMAL) {
 4387|                     if(enforce_hardbreak)
 4388|                         break_type = MD_TEXT_BR;
 4389|                     else if((CH(line->end) == _T(' ') && CH(line->end+1) == _T(' ')))
 4390|                         break_type = MD_TEXT_BR;
 4391|                 }
 4392| 
 4393|                 MD_TEXT(break_type, _T("\n"), 1);
 4394|             }
 4395| 
 4396|             /* Move to the next line. */
 4397|             line++;
 4398|             off = line->beg;
 4399| 
 4400|             enforce_hardbreak = 0;
 4401|         }
 4402|     }
 4403| 
 4404| abort:
 4405|     return ret;
 4406| }
