 4413| static void
 4414| md_analyze_table_alignment(MD_CTX* ctx, OFF beg, OFF end, MD_ALIGN* align, int n_align)
 4415| {
 4416|     static const MD_ALIGN align_map[] = { MD_ALIGN_DEFAULT, MD_ALIGN_LEFT, MD_ALIGN_RIGHT, MD_ALIGN_CENTER };
 4417|     OFF off = beg;
 4418| 
 4419|     while(n_align > 0) {
 4420|         int index = 0;  /* index into align_map[] */
 4421| 
 4422|         while(CH(off) != _T('-'))
 4423|             off++;
 4424|         if(off > beg  &&  CH(off-1) == _T(':'))
 4425|             index |= 1;
 4426|         while(off < end  &&  CH(off) == _T('-'))
 4427|             off++;
 4428|         if(off < end  &&  CH(off) == _T(':'))
 4429|             index |= 2;
 4430| 
 4431|         *align = align_map[index];
 4432|         align++;
 4433|         n_align--;
 4434|     }
 4435| 
 4436| }
