 4465| static int
 4466| md_process_table_row(MD_CTX* ctx, MD_BLOCKTYPE cell_type, OFF beg, OFF end,
 4467|                      const MD_ALIGN* align, int col_count)
 4468| {
 4469|     MD_LINE line;
 4470|     OFF* pipe_offs = NULL;
 4471|     int i, j, k, n;
 4472|     int ret = 0;
 4473| 
 4474|     line.beg = beg;
 4475|     line.end = end;
 4476| 
 4477|     /* Break the line into table cells by identifying pipe characters who
 4478|      * form the cell boundary. */
 4479|     MD_CHECK(md_analyze_inlines(ctx, &line, 1, TRUE));
 4480| 
 4481|     /* We have to remember the cell boundaries in local buffer because
 4482|      * ctx->marks[] shall be reused during cell contents processing. */
 4483|     n = ctx->n_table_cell_boundaries + 2;
 4484|     pipe_offs = (OFF*) malloc(n * sizeof(OFF));
 4485|     if(pipe_offs == NULL) {
 4486|         MD_LOG("malloc() failed.");
 4487|         ret = -1;
 4488|         goto abort;
 4489|     }
 4490|     j = 0;
 4491|     pipe_offs[j++] = beg;
 4492|     for(i = TABLECELLBOUNDARIES.head; i >= 0; i = ctx->marks[i].next) {
 4493|         MD_MARK* mark = &ctx->marks[i];
 4494|         pipe_offs[j++] = mark->end;
 4495|     }
 4496|     pipe_offs[j++] = end+1;
 4497| 
 4498|     /* Process cells. */
 4499|     MD_ENTER_BLOCK(MD_BLOCK_TR, NULL);
 4500|     k = 0;
 4501|     for(i = 0; i < j-1  &&  k < col_count; i++) {
 4502|         if(pipe_offs[i] < pipe_offs[i+1]-1)
 4503|             MD_CHECK(md_process_table_cell(ctx, cell_type, align[k++], pipe_offs[i], pipe_offs[i+1]-1));
 4504|     }
 4505|     /* Make sure we call enough table cells even if the current table contains
 4506|      * too few of them. */
 4507|     while(k < col_count)
 4508|         MD_CHECK(md_process_table_cell(ctx, cell_type, align[k++], 0, 0));
 4509|     MD_LEAVE_BLOCK(MD_BLOCK_TR, NULL);
 4510| 
 4511| abort:
 4512|     free(pipe_offs);
 4513| 
 4514|     /* Free any temporary memory blocks stored within some dummy marks. */
 4515|     for(i = PTR_CHAIN.head; i >= 0; i = ctx->marks[i].next)
 4516|         free(md_mark_get_ptr(ctx, i));
 4517|     PTR_CHAIN.head = -1;
 4518|     PTR_CHAIN.tail = -1;
 4519| 
 4520|     return ret;
 4521| }
 4522| 
 4523| static int
 4524| md_process_table_block_contents(MD_CTX* ctx, int col_count, const MD_LINE* lines, int n_lines)
 4525| {
 4526|     MD_ALIGN* align;
 4527|     int i;
 4528|     int ret = 0;
 4529| 
 4530|     /* At least two lines have to be present: The column headers and the line
 4531|      * with the underlines. */
 4532|     MD_ASSERT(n_lines >= 2);
 4533| 
 4534|     align = malloc(col_count * sizeof(MD_ALIGN));
 4535|     if(align == NULL) {
 4536|         MD_LOG("malloc() failed.");
 4537|         ret = -1;
 4538|         goto abort;
 4539|     }
 4540| 
 4541|     md_analyze_table_alignment(ctx, lines[1].beg, lines[1].end, align, col_count);
 4542| 
 4543|     MD_ENTER_BLOCK(MD_BLOCK_THEAD, NULL);
 4544|     MD_CHECK(md_process_table_row(ctx, MD_BLOCK_TH,
 4545|                         lines[0].beg, lines[0].end, align, col_count));
 4546|     MD_LEAVE_BLOCK(MD_BLOCK_THEAD, NULL);
 4547| 
 4548|     if(n_lines > 2) {
 4549|         MD_ENTER_BLOCK(MD_BLOCK_TBODY, NULL);
 4550|         for(i = 2; i < n_lines; i++) {
 4551|             MD_CHECK(md_process_table_row(ctx, MD_BLOCK_TD,
 4552|                      lines[i].beg, lines[i].end, align, col_count));
 4553|         }
 4554|         MD_LEAVE_BLOCK(MD_BLOCK_TBODY, NULL);
 4555|     }
 4556| 
 4557| abort:
 4558|     free(align);
 4559|     return ret;
 4560| }
