 4622| static int
 4623| md_process_verbatim_block_contents(MD_CTX* ctx, MD_TEXTTYPE text_type, const MD_VERBATIMLINE* lines, int n_lines)
 4624| {
 4625|     static const CHAR indent_chunk_str[] = _T("                ");
 4626|     static const SZ indent_chunk_size = SIZEOF_ARRAY(indent_chunk_str) - 1;
 4627| 
 4628|     int i;
 4629|     int ret = 0;
 4630| 
 4631|     for(i = 0; i < n_lines; i++) {
 4632|         const MD_VERBATIMLINE* line = &lines[i];
 4633|         int indent = line->indent;
 4634| 
 4635|         MD_ASSERT(indent >= 0);
 4636| 
 4637|         /* Output code indentation. */
 4638|         while(indent > (int) indent_chunk_size) {
 4639|             MD_TEXT(text_type, indent_chunk_str, indent_chunk_size);
 4640|             indent -= indent_chunk_size;
 4641|         }
 4642|         if(indent > 0)
 4643|             MD_TEXT(text_type, indent_chunk_str, indent);
 4644| 
 4645|         /* Output the code line itself. */
 4646|         MD_TEXT_INSECURE(text_type, STR(line->beg), line->end - line->beg);
 4647| 
 4648|         /* Enforce end-of-line. */
 4649|         MD_TEXT(text_type, _T("\n"), 1);
 4650|     }
 4651| 
 4652| abort:
 4653|     return ret;
 4654| }
