 4656| static int
 4657| md_process_code_block_contents(MD_CTX* ctx, int is_fenced, const MD_VERBATIMLINE* lines, int n_lines)
 4658| {
 4659|     if(is_fenced) {
 4660|         /* Skip the first line in case of fenced code: It is the fence.
 4661|          * (Only the starting fence is present due to logic in md_analyze_line().) */
 4662|         lines++;
 4663|         n_lines--;
 4664|     } else {
 4665|         /* Ignore blank lines at start/end of indented code block. */
 4666|         while(n_lines > 0  &&  lines[0].beg == lines[0].end) {
 4667|             lines++;
 4668|             n_lines--;
 4669|         }
 4670|         while(n_lines > 0  &&  lines[n_lines-1].beg == lines[n_lines-1].end) {
 4671|             n_lines--;
 4672|         }
 4673|     }
 4674| 
 4675|     if(n_lines == 0)
 4676|         return 0;
 4677| 
 4678|     return md_process_verbatim_block_contents(ctx, MD_TEXT_CODE, lines, n_lines);
 4679| }
