 4681| static int
 4682| md_setup_fenced_code_detail(MD_CTX* ctx, const MD_BLOCK* block, MD_BLOCK_CODE_DETAIL* det,
 4683|                             MD_ATTRIBUTE_BUILD* info_build, MD_ATTRIBUTE_BUILD* lang_build)
 4684| {
 4685|     const MD_VERBATIMLINE* fence_line = (const MD_VERBATIMLINE*)(block + 1);
 4686|     OFF beg = fence_line->beg;
 4687|     OFF end = fence_line->end;
 4688|     OFF lang_end;
 4689|     CHAR fence_ch = CH(fence_line->beg);
 4690|     int ret = 0;
 4691| 
 4692|     /* Skip the fence itself. */
 4693|     while(beg < ctx->size  &&  CH(beg) == fence_ch)
 4694|         beg++;
 4695|     /* Trim initial spaces. */
 4696|     while(beg < ctx->size  &&  CH(beg) == _T(' '))
 4697|         beg++;
 4698| 
 4699|     /* Trim trailing spaces. */
 4700|     while(end > beg  &&  CH(end-1) == _T(' '))
 4701|         end--;
 4702| 
 4703|     /* Build info string attribute. */
 4704|     MD_CHECK(md_build_attribute(ctx, STR(beg), end - beg, 0, &det->info, info_build));
 4705| 
 4706|     /* Build info string attribute. */
 4707|     lang_end = beg;
 4708|     while(lang_end < end  &&  !ISWHITESPACE(lang_end))
 4709|         lang_end++;
 4710|     MD_CHECK(md_build_attribute(ctx, STR(beg), lang_end - beg, 0, &det->lang, lang_build));
 4711| 
 4712|     det->fence_char = fence_ch;
 4713| 
 4714| abort:
 4715|     return ret;
 4716| }
