 4718| static int
 4719| md_process_leaf_block(MD_CTX* ctx, const MD_BLOCK* block)
 4720| {
 4721|     union {
 4722|         MD_BLOCK_H_DETAIL header;
 4723|         MD_BLOCK_CODE_DETAIL code;
 4724|         MD_BLOCK_TABLE_DETAIL table;
 4725|     } det;
 4726|     MD_ATTRIBUTE_BUILD info_build;
 4727|     MD_ATTRIBUTE_BUILD lang_build;
 4728|     int is_in_tight_list;
 4729|     int clean_fence_code_detail = FALSE;
 4730|     int ret = 0;
 4731| 
 4732|     memset(&det, 0, sizeof(det));
 4733| 
 4734|     if(ctx->n_containers == 0)
 4735|         is_in_tight_list = FALSE;
 4736|     else
 4737|         is_in_tight_list = !ctx->containers[ctx->n_containers-1].is_loose;
 4738| 
 4739|     switch(block->type) {
 4740|         case MD_BLOCK_H:
 4741|             det.header.level = block->data;
 4742|             break;
 4743| 
 4744|         case MD_BLOCK_CODE:
 4745|             /* For fenced code block, we may need to set the info string. */
 4746|             if(block->data != 0) {
 4747|                 memset(&det.code, 0, sizeof(MD_BLOCK_CODE_DETAIL));
 4748|                 clean_fence_code_detail = TRUE;
 4749|                 MD_CHECK(md_setup_fenced_code_detail(ctx, block, &det.code, &info_build, &lang_build));
 4750|             }
 4751|             break;
 4752| 
 4753|         case MD_BLOCK_TABLE:
 4754|             det.table.col_count = block->data;
 4755|             det.table.head_row_count = 1;
 4756|             det.table.body_row_count = block->n_lines - 2;
 4757|             break;
 4758| 
 4759|         default:
 4760|             /* Noop. */
 4761|             break;
 4762|     }
 4763| 
 4764|     if(!is_in_tight_list  ||  block->type != MD_BLOCK_P)
 4765|         MD_ENTER_BLOCK(block->type, (void*) &det);
 4766| 
 4767|     /* Process the block contents accordingly to is type. */
 4768|     switch(block->type) {
 4769|         case MD_BLOCK_HR:
 4770|             /* noop */
 4771|             break;
 4772| 
 4773|         case MD_BLOCK_CODE:
 4774|             MD_CHECK(md_process_code_block_contents(ctx, (block->data != 0),
 4775|                             (const MD_VERBATIMLINE*)(block + 1), block->n_lines));
 4776|             break;
 4777| 
 4778|         case MD_BLOCK_HTML:
 4779|             MD_CHECK(md_process_verbatim_block_contents(ctx, MD_TEXT_HTML,
 4780|                             (const MD_VERBATIMLINE*)(block + 1), block->n_lines));
 4781|             break;
 4782| 
 4783|         case MD_BLOCK_TABLE:
 4784|             MD_CHECK(md_process_table_block_contents(ctx, block->data,
 4785|                             (const MD_LINE*)(block + 1), block->n_lines));
 4786|             break;
 4787| 
 4788|         default:
 4789|             MD_CHECK(md_process_normal_block_contents(ctx,
 4790|                             (const MD_LINE*)(block + 1), block->n_lines));
 4791|             break;
 4792|     }
 4793| 
 4794|     if(!is_in_tight_list  ||  block->type != MD_BLOCK_P)
 4795|         MD_LEAVE_BLOCK(block->type, (void*) &det);
 4796| 
 4797| abort:
 4798|     if(clean_fence_code_detail) {
 4799|         md_free_attribute(ctx, &info_build);
 4800|         md_free_attribute(ctx, &lang_build);
 4801|     }
 4802|     return ret;
 4803| }
