 4805| static int
 4806| md_process_all_blocks(MD_CTX* ctx)
 4807| {
 4808|     int byte_off = 0;
 4809|     int ret = 0;
 4810| 
 4811|     /* ctx->containers now is not needed for detection of lists and list items
 4812|      * so we reuse it for tracking what lists are loose or tight. We rely
 4813|      * on the fact the vector is large enough to hold the deepest nesting
 4814|      * level of lists. */
 4815|     ctx->n_containers = 0;
 4816| 
 4817|     while(byte_off < ctx->n_block_bytes) {
 4818|         MD_BLOCK* block = (MD_BLOCK*)((char*)ctx->block_bytes + byte_off);
 4819|         union {
 4820|             MD_BLOCK_UL_DETAIL ul;
 4821|             MD_BLOCK_OL_DETAIL ol;
 4822|             MD_BLOCK_LI_DETAIL li;
 4823|         } det;
 4824| 
 4825|         switch(block->type) {
 4826|             case MD_BLOCK_UL:
 4827|                 det.ul.is_tight = (block->flags & MD_BLOCK_LOOSE_LIST) ? FALSE : TRUE;
 4828|                 det.ul.mark = (CHAR) block->data;
 4829|                 break;
 4830| 
 4831|             case MD_BLOCK_OL:
 4832|                 det.ol.start = block->n_lines;
 4833|                 det.ol.is_tight =  (block->flags & MD_BLOCK_LOOSE_LIST) ? FALSE : TRUE;
 4834|                 det.ol.mark_delimiter = (CHAR) block->data;
 4835|                 break;
 4836| 
 4837|             case MD_BLOCK_LI:
 4838|                 det.li.is_task = (block->data != 0);
 4839|                 det.li.task_mark = (CHAR) block->data;
 4840|                 det.li.task_mark_offset = (OFF) block->n_lines;
 4841|                 break;
 4842| 
 4843|             default:
 4844|                 /* noop */
 4845|                 break;
 4846|         }
 4847| 
 4848|         if(block->flags & MD_BLOCK_CONTAINER) {
 4849|             if(block->flags & MD_BLOCK_CONTAINER_CLOSER) {
 4850|                 MD_LEAVE_BLOCK(block->type, &det);
 4851| 
 4852|                 if(block->type == MD_BLOCK_UL || block->type == MD_BLOCK_OL || block->type == MD_BLOCK_QUOTE)
 4853|                     ctx->n_containers--;
 4854|             }
 4855| 
 4856|             if(block->flags & MD_BLOCK_CONTAINER_OPENER) {
 4857|                 MD_ENTER_BLOCK(block->type, &det);
 4858| 
 4859|                 if(block->type == MD_BLOCK_UL || block->type == MD_BLOCK_OL) {
 4860|                     ctx->containers[ctx->n_containers].is_loose = (block->flags & MD_BLOCK_LOOSE_LIST);
 4861|                     ctx->n_containers++;
 4862|                 } else if(block->type == MD_BLOCK_QUOTE) {
 4863|                     /* This causes that any text in a block quote, even if
 4864|                      * nested inside a tight list item, is wrapped with
 4865|                      * <p>...</p>. */
 4866|                     ctx->containers[ctx->n_containers].is_loose = TRUE;
 4867|                     ctx->n_containers++;
 4868|                 }
 4869|             }
 4870|         } else {
 4871|             MD_CHECK(md_process_leaf_block(ctx, block));
 4872| 
 4873|             if(block->type == MD_BLOCK_CODE || block->type == MD_BLOCK_HTML)
 4874|                 byte_off += block->n_lines * sizeof(MD_VERBATIMLINE);
 4875|             else
 4876|                 byte_off += block->n_lines * sizeof(MD_LINE);
 4877|         }
 4878| 
 4879|         byte_off += sizeof(MD_BLOCK);
 4880|     }
 4881| 
 4882|     ctx->n_block_bytes = 0;
 4883| 
 4884| abort:
 4885|     return ret;
 4886| }
