 4889| /************************************
 4890|  ***  Grouping Lines into Blocks  ***
 4891|  ************************************/
 4892| 
 4893| static void*
 4894| md_push_block_bytes(MD_CTX* ctx, int n_bytes)
 4895| {
 4896|     void* ptr;
 4897| 
 4898|     if(ctx->n_block_bytes + n_bytes > ctx->alloc_block_bytes) {
 4899|         void* new_block_bytes;
 4900| 
 4901|         ctx->alloc_block_bytes = (ctx->alloc_block_bytes > 0
 4902|                 ? ctx->alloc_block_bytes + ctx->alloc_block_bytes / 2
 4903|                 : 512);
 4904|         new_block_bytes = realloc(ctx->block_bytes, ctx->alloc_block_bytes);
 4905|         if(new_block_bytes == NULL) {
 4906|             MD_LOG("realloc() failed.");
 4907|             return NULL;
 4908|         }
 4909| 
 4910|         /* Fix the ->current_block after the reallocation. */
 4911|         if(ctx->current_block != NULL) {
 4912|             OFF off_current_block = (OFF) ((char*) ctx->current_block - (char*) ctx->block_bytes);
 4913|             ctx->current_block = (MD_BLOCK*) ((char*) new_block_bytes + off_current_block);
 4914|         }
 4915| 
 4916|         ctx->block_bytes = new_block_bytes;
 4917|     }
 4918| 
 4919|     ptr = (char*)ctx->block_bytes + ctx->n_block_bytes;
 4920|     ctx->n_block_bytes += n_bytes;
 4921|     return ptr;
 4922| }
