 4929|     MD_ASSERT(ctx->current_block == NULL);
 4930| 
 4931|     block = (MD_BLOCK*) md_push_block_bytes(ctx, sizeof(MD_BLOCK));
 4932|     if(block == NULL)
 4933|         return -1;
 4934| 
 4935|     switch(line->type) {
 4936|         case MD_LINE_HR:
 4937|             block->type = MD_BLOCK_HR;
 4938|             break;
 4939| 
 4940|         case MD_LINE_ATXHEADER:
 4941|         case MD_LINE_SETEXTHEADER:
 4942|             block->type = MD_BLOCK_H;
 4943|             break;
 4944| 
 4945|         case MD_LINE_FENCEDCODE:
 4946|         case MD_LINE_INDENTEDCODE:
 4947|             block->type = MD_BLOCK_CODE;
 4948|             break;
 4949| 
 4950|         case MD_LINE_TEXT:
 4951|             block->type = MD_BLOCK_P;
 4952|             break;
 4953| 
 4954|         case MD_LINE_HTML:
 4955|             block->type = MD_BLOCK_HTML;
 4956|             break;
