 4974| /* Eat from start of current (textual) block any reference definitions and
 4975|  * remember them so we can resolve any links referring to them.
 4976|  *
 4977|  * (Reference definitions can only be at start of it as they cannot break
 4978|  * a paragraph.)
 4979|  */
 4980| static int
 4981| md_consume_link_reference_definitions(MD_CTX* ctx)
 4982| {
 4983|     MD_LINE* lines = (MD_LINE*) (ctx->current_block + 1);
 4984|     int n_lines = ctx->current_block->n_lines;
 4985|     int n = 0;
 4986| 
 4987|     /* Compute how many lines at the start of the block form one or more
 4988|      * reference definitions. */
 4989|     while(n < n_lines) {
 4990|         int n_link_ref_lines;
 4991| 
 4992|         n_link_ref_lines = md_is_link_reference_definition(ctx,
 4993|                                     lines + n, n_lines - n);
 4994|         /* Not a reference definition? */
 4995|         if(n_link_ref_lines == 0)
 4996|             break;
 4997| 
 4998|         /* We fail if it is the ref. def. but it could not be stored due
 4999|          * a memory allocation error. */
 5000|         if(n_link_ref_lines < 0)
 5001|             return -1;
 5002| 
 5003|         n += n_link_ref_lines;
 5004|     }
 5005| 
 5006|     /* If there was at least one reference definition, we need to remove
 5007|      * its lines from the block, or perhaps even the whole block. */
 5008|     if(n > 0) {
 5009|         if(n == n_lines) {
 5010|             /* Remove complete block. */
 5011|             ctx->n_block_bytes -= n * sizeof(MD_LINE);
 5012|             ctx->n_block_bytes -= sizeof(MD_BLOCK);
 5013|             ctx->current_block = NULL;
 5014|         } else {
 5015|             /* Remove just some initial lines from the block. */
 5016|             memmove(lines, lines + n, (n_lines - n) * sizeof(MD_LINE));
 5017|             ctx->current_block->n_lines -= n;
 5018|             ctx->n_block_bytes -= n * sizeof(MD_LINE);
 5019|         }
 5020|     }
 5021| 
 5022|     return 0;
 5023| }
 5024| 
 5025| static int
 5026| md_end_current_block(MD_CTX* ctx)
 5027| {
 5028|     int ret = 0;
 5029| 
 5030|     if(ctx->current_block == NULL)
 5031|         return ret;
 5032| 
 5033|     /* Check whether there is a reference definition. (We do this here instead
 5034|      * of in md_analyze_line() because reference definition can take multiple
 5035|      * lines.) */
 5036|     if(ctx->current_block->type == MD_BLOCK_P  ||
 5037|        (ctx->current_block->type == MD_BLOCK_H  &&  (ctx->current_block->flags & MD_BLOCK_SETEXT_HEADER)))
 5038|     {
 5039|         MD_LINE* lines = (MD_LINE*) (ctx->current_block + 1);
 5040|         if(CH(lines[0].beg) == _T('[')) {
 5041|             MD_CHECK(md_consume_link_reference_definitions(ctx));
 5042|             if(ctx->current_block == NULL)
 5043|                 return ret;
 5044|         }
 5045|     }
 5046| 
 5047|     if(ctx->current_block->type == MD_BLOCK_H  &&  (ctx->current_block->flags & MD_BLOCK_SETEXT_HEADER)) {
 5048|         int n_lines = ctx->current_block->n_lines;
 5049| 
 5050|         if(n_lines > 1) {
 5051|             /* Get rid of the underline. */
 5052|             ctx->current_block->n_lines--;
 5053|             ctx->n_block_bytes -= sizeof(MD_LINE);
 5054|         } else {
 5055|             /* Only the underline has left after eating the ref. defs.
 5056|              * Keep the line as beginning of a new ordinary paragraph. */
 5057|             ctx->current_block->type = MD_BLOCK_P;
 5058|             return 0;
 5059|         }
 5060|     }
 5061| 
 5062|     /* Mark we are not building any block anymore. */
 5063|     ctx->current_block = NULL;
 5064| 
 5065| abort:
 5066|     return ret;
 5067| }
