 5123| /***********************
 5124|  ***  Line Analysis  ***
 5125|  ***********************/
 5126| 
 5127| static int
 5128| md_is_hr_line(MD_CTX* ctx, OFF beg, OFF* p_end, OFF* p_killer)
 5129| {
 5130|     OFF off = beg + 1;
 5131|     int n = 1;
 5132| 
 5133|     while(off < ctx->size  &&  (CH(off) == CH(beg) || CH(off) == _T(' ') || CH(off) == _T('\t'))) {
 5134|         if(CH(off) == CH(beg))
 5135|             n++;
 5136|         off++;
 5137|     }
 5138| 
 5139|     if(n < 3) {
 5140|         *p_killer = off;
 5141|         return FALSE;
 5142|     }
 5143| 
 5144|     /* Nothing else can be present on the line. */
 5145|     if(off < ctx->size  &&  !ISNEWLINE(off)) {
 5146|         *p_killer = off;
 5147|         return FALSE;
 5148|     }
 5149| 
 5150|     *p_end = off;
 5151|     return TRUE;
 5152| }
 5153| 
 5154| static int
 5155| md_is_atxheader_line(MD_CTX* ctx, OFF beg, OFF* p_beg, OFF* p_end, unsigned* p_level)
 5156| {
 5157|     int n;
 5158|     OFF off = beg + 1;
 5159| 
 5160|     while(off < ctx->size  &&  CH(off) == _T('#')  &&  off - beg < 7)
 5161|         off++;
 5162|     n = off - beg;
 5163| 
 5164|     if(n > 6)
 5165|         return FALSE;
 5166|     *p_level = n;
 5167| 
 5168|     if(!(ctx->parser.flags & MD_FLAG_PERMISSIVEATXHEADERS)  &&  off < ctx->size  &&
 5169|        CH(off) != _T(' ')  &&  CH(off) != _T('\t')  &&  !ISNEWLINE(off))
 5170|         return FALSE;
 5171| 
 5172|     while(off < ctx->size  &&  CH(off) == _T(' '))
 5173|         off++;
 5174|     *p_beg = off;
 5175|     *p_end = off;
 5176|     return TRUE;
 5177| }
 5178| 
 5179| static int
 5180| md_is_setext_underline(MD_CTX* ctx, OFF beg, OFF* p_end, unsigned* p_level)
 5181| {
 5182|     OFF off = beg + 1;
 5183| 
 5184|     while(off < ctx->size  &&  CH(off) == CH(beg))
 5185|         off++;
 5186| 
 5187|     /* Optionally, space(s) can follow. */
 5188|     while(off < ctx->size  &&  CH(off) == _T(' '))
 5189|         off++;
 5190| 
 5191|     /* But nothing more is allowed on the line. */
 5192|     if(off < ctx->size  &&  !ISNEWLINE(off))
 5193|         return FALSE;
 5194| 
 5195|     *p_level = (CH(beg) == _T('=') ? 1 : 2);
 5196|     *p_end = off;
 5197|     return TRUE;
 5198| }
 5199| 
 5200| static int
 5201| md_is_table_underline(MD_CTX* ctx, OFF beg, OFF* p_end, unsigned* p_col_count)
 5202| {
 5203|     OFF off = beg;
 5204|     int found_pipe = FALSE;
 5205|     unsigned col_count = 0;
 5206| 
 5207|     if(off < ctx->size  &&  CH(off) == _T('|')) {
 5208|         found_pipe = TRUE;
 5209|         off++;
 5210|         while(off < ctx->size  &&  ISWHITESPACE(off))
 5211|             off++;
 5212|     }
 5213| 
 5214|     while(1) {
 5215|         OFF cell_beg;
 5216|         int delimited = FALSE;
 5217| 
 5218|         /* Cell underline ("-----", ":----", "----:" or ":----:") */
 5219|         cell_beg = off;
 5220|         if(off < ctx->size  &&  CH(off) == _T(':'))
 5221|             off++;
 5222|         while(off < ctx->size  &&  CH(off) == _T('-'))
 5223|             off++;
 5224|         if(off < ctx->size  &&  CH(off) == _T(':'))
 5225|             off++;
 5226|         if(off - cell_beg < 3)
 5227|             return FALSE;
 5228| 
 5229|         col_count++;
 5230| 
 5231|         /* Pipe delimiter (optional at the end of line). */
 5232|         while(off < ctx->size  &&  ISWHITESPACE(off))
 5233|             off++;
 5234|         if(off < ctx->size  &&  CH(off) == _T('|')) {
 5235|             delimited = TRUE;
 5236|             found_pipe =  TRUE;
 5237|             off++;
 5238|             while(off < ctx->size  &&  ISWHITESPACE(off))
 5239|                 off++;
 5240|         }
 5241| 
 5242|         /* Success, if we reach end of line. */
 5243|         if(off >= ctx->size  ||  ISNEWLINE(off))
 5244|             break;
 5245| 
 5246|         if(!delimited)
 5247|             return FALSE;
 5248|     }
 5249| 
 5250|     if(!found_pipe)
 5251|         return FALSE;
 5252| 
 5253|     *p_end = off;
 5254|     *p_col_count = col_count;
 5255|     return TRUE;
 5256| }
 5257| 
 5258| static int
 5259| md_is_opening_code_fence(MD_CTX* ctx, OFF beg, OFF* p_end)
 5260| {
 5261|     OFF off = beg;
 5262| 
 5263|     while(off < ctx->size && CH(off) == CH(beg))
 5264|         off++;
 5265| 
 5266|     /* Fence must have at least three characters. */
 5267|     if(off - beg < 3)
 5268|         return FALSE;
 5269| 
 5270|     ctx->code_fence_length = off - beg;
 5271| 
 5272|     /* Optionally, space(s) can follow. */
 5273|     while(off < ctx->size  &&  CH(off) == _T(' '))
 5274|         off++;
 5275| 
 5276|     /* Optionally, an info string can follow. */
 5277|     while(off < ctx->size  &&  !ISNEWLINE(off)) {
 5278|         /* Backtick-based fence must not contain '`' in the info string. */
 5279|         if(CH(beg) == _T('`')  &&  CH(off) == _T('`'))
 5280|             return FALSE;
 5281|         off++;
 5282|     }
 5283| 
 5284|     *p_end = off;
 5285|     return TRUE;
 5286| }
 5287| 
 5288| static int
 5289| md_is_closing_code_fence(MD_CTX* ctx, CHAR ch, OFF beg, OFF* p_end)
 5290| {
 5291|     OFF off = beg;
 5292|     int ret = FALSE;
 5293| 
 5294|     /* Closing fence must have at least the same length and use same char as
 5295|      * opening one. */
 5296|     while(off < ctx->size  &&  CH(off) == ch)
 5297|         off++;
 5298|     if(off - beg < ctx->code_fence_length)
 5299|         goto out;
 5300| 
 5301|     /* Optionally, space(s) can follow */
 5302|     while(off < ctx->size  &&  CH(off) == _T(' '))
 5303|         off++;
 5304| 
 5305|     /* But nothing more is allowed on the line. */
 5306|     if(off < ctx->size  &&  !ISNEWLINE(off))
 5307|         goto out;
 5308| 
 5309|     ret = TRUE;
 5310| 
 5311| out:
 5312|     /* Note we set *p_end even on failure: If we are not closing fence, caller
 5313|      * would eat the line anyway without any parsing. */
 5314|     *p_end = off;
 5315|     return ret;
 5316| }
