 5519| static int
 5520| md_is_container_compatible(const MD_CONTAINER* pivot, const MD_CONTAINER* container)
 5521| {
 5522|     /* Block quote has no "items" like lists. */
 5523|     if(container->ch == _T('>'))
 5524|         return FALSE;
 5525| 
 5526|     if(container->ch != pivot->ch)
 5527|         return FALSE;
 5528|     if(container->mark_indent > pivot->contents_indent)
 5529|         return FALSE;
 5530| 
 5531|     return TRUE;
 5532| }
