 5534| static int
 5535| md_push_container(MD_CTX* ctx, const MD_CONTAINER* container)
 5536| {
 5537|     if(ctx->n_containers >= ctx->alloc_containers) {
 5538|         MD_CONTAINER* new_containers;
 5539| 
 5540|         ctx->alloc_containers = (ctx->alloc_containers > 0
 5541|                 ? ctx->alloc_containers + ctx->alloc_containers / 2
 5542|                 : 16);
 5543|         new_containers = realloc(ctx->containers, ctx->alloc_containers * sizeof(MD_CONTAINER));
 5544|         if(new_containers == NULL) {
 5545|             MD_LOG("realloc() failed.");
 5546|             return -1;
 5547|         }
 5548| 
 5549|         ctx->containers = new_containers;
 5550|     }
 5551| 
 5552|     memcpy(&ctx->containers[ctx->n_containers++], container, sizeof(MD_CONTAINER));
 5553|     return 0;
 5554| }
