 5556| static int
 5557| md_enter_child_containers(MD_CTX* ctx, int n_children)
 5558| {
 5559|     int i;
 5560|     int ret = 0;
 5561| 
 5562|     for(i = ctx->n_containers - n_children; i < ctx->n_containers; i++) {
 5563|         MD_CONTAINER* c = &ctx->containers[i];
 5564|         int is_ordered_list = FALSE;
 5565| 
 5566|         switch(c->ch) {
 5567|             case _T(')'):
 5568|             case _T('.'):
 5569|                 is_ordered_list = TRUE;
 5570|                 MD_FALLTHROUGH();
 5571| 
 5572|             case _T('-'):
 5573|             case _T('+'):
 5574|             case _T('*'):
 5575|                 /* Remember offset in ctx->block_bytes so we can revisit the
 5576|                  * block if we detect it is a loose list. */
 5577|                 md_end_current_block(ctx);
 5578|                 c->block_byte_off = ctx->n_block_bytes;
 5579| 
 5580|                 MD_CHECK(md_push_container_bytes(ctx,
 5581|                                 (is_ordered_list ? MD_BLOCK_OL : MD_BLOCK_UL),
 5582|                                 c->start, c->ch, MD_BLOCK_CONTAINER_OPENER));
 5583|                 MD_CHECK(md_push_container_bytes(ctx, MD_BLOCK_LI,
 5584|                                 c->task_mark_off,
 5585|                                 (c->is_task ? CH(c->task_mark_off) : 0),
 5586|                                 MD_BLOCK_CONTAINER_OPENER));
 5587|                 break;
 5588| 
 5589|             case _T('>'):
 5590|                 MD_CHECK(md_push_container_bytes(ctx, MD_BLOCK_QUOTE, 0, 0, MD_BLOCK_CONTAINER_OPENER));
 5591|                 break;
 5592| 
 5593|             default:
 5594|                 MD_UNREACHABLE();
 5595|                 break;
 5596|         }
 5597|     }
 5598| 
 5599| abort:
 5600|     return ret;
 5601| }
