 5603| static int
 5604| md_leave_child_containers(MD_CTX* ctx, int n_keep)
 5605| {
 5606|     int ret = 0;
 5607| 
 5608|     while(ctx->n_containers > n_keep) {
 5609|         MD_CONTAINER* c = &ctx->containers[ctx->n_containers-1];
 5610|         int is_ordered_list = FALSE;
 5611| 
 5612|         switch(c->ch) {
 5613|             case _T(')'):
 5614|             case _T('.'):
 5615|                 is_ordered_list = TRUE;
 5616|                 MD_FALLTHROUGH();
 5617| 
 5618|             case _T('-'):
 5619|             case _T('+'):
 5620|             case _T('*'):
 5621|                 MD_CHECK(md_push_container_bytes(ctx, MD_BLOCK_LI,
 5622|                                 c->task_mark_off, (c->is_task ? CH(c->task_mark_off) : 0),
 5623|                                 MD_BLOCK_CONTAINER_CLOSER));
 5624|                 MD_CHECK(md_push_container_bytes(ctx,
 5625|                                 (is_ordered_list ? MD_BLOCK_OL : MD_BLOCK_UL), 0,
 5626|                                 c->ch, MD_BLOCK_CONTAINER_CLOSER));
 5627|                 break;
 5628| 
 5629|             case _T('>'):
 5630|                 MD_CHECK(md_push_container_bytes(ctx, MD_BLOCK_QUOTE, 0,
