 5703| static unsigned
 5704| md_line_indentation(MD_CTX* ctx, unsigned total_indent, OFF beg, OFF* p_end)
 5705| {
 5706|     OFF off = beg;
 5707|     unsigned indent = total_indent;
 5708| 
 5709|     while(off < ctx->size  &&  ISBLANK(off)) {
 5710|         if(CH(off) == _T('\t'))
 5711|             indent = (indent + 4) & ~3;
 5712|         else
 5713|             indent++;
 5714|         off++;
 5715|     }
 5716| 
 5717|     *p_end = off;
 5718|     return indent - total_indent;
 5719| }
