 5721| static const MD_LINE_ANALYSIS md_dummy_blank_line = { MD_LINE_BLANK, 0, 0, 0, 0 };
 5722| 
 5723| /* Analyze type of the line and find some its properties. This serves as a
 5724|  * main input for determining type and boundaries of a block. */
 5725| static int
 5726| md_analyze_line(MD_CTX* ctx, OFF beg, OFF* p_end,
 5727|                 const MD_LINE_ANALYSIS* pivot_line, MD_LINE_ANALYSIS* line)
 5728| {
 5729|     unsigned total_indent = 0;
 5730|     int n_parents = 0;
 5731|     int n_brothers = 0;
 5732|     int n_children = 0;
 5733|     MD_CONTAINER container = { 0 };
 5734|     int prev_line_has_list_loosening_effect = ctx->last_line_has_list_loosening_effect;
 5735|     OFF off = beg;
 5736|     OFF hr_killer = 0;
 5737|     int ret = 0;
 5738| 
 5739|     line->indent = md_line_indentation(ctx, total_indent, off, &off);
 5740|     total_indent += line->indent;
 5741|     line->beg = off;
 5742| 
 5743|     /* Given the indentation and block quote marks '>', determine how many of
 5744|      * the current containers are our parents. */
 5745|     while(n_parents < ctx->n_containers) {
 5746|         MD_CONTAINER* c = &ctx->containers[n_parents];
 5747| 
 5748|         if(c->ch == _T('>')  &&  line->indent < ctx->code_indent_offset  &&
 5749|             off < ctx->size  &&  CH(off) == _T('>'))
 5750|         {
 5751|             /* Block quote mark. */
 5752|             off++;
 5753|             total_indent++;
 5754|             line->indent = md_line_indentation(ctx, total_indent, off, &off);
 5755|             total_indent += line->indent;
 5756| 
 5757|             /* The optional 1st space after '>' is part of the block quote mark. */
 5758|             if(line->indent > 0)
 5759|                 line->indent--;
 5760| 
 5761|             line->beg = off;
 5762| 
 5763|         } else if(c->ch != _T('>')  &&  line->indent >= c->contents_indent) {
 5764|             /* List. */
 5765|             line->indent -= c->contents_indent;
 5766|         } else {
 5767|             break;
 5768|         }
 5769| 
 5770|         n_parents++;
 5771|     }
 5772| 
 5773|     if(off >= ctx->size  ||  ISNEWLINE(off)) {
 5774|         /* Blank line does not need any real indentation to be nested inside
 5775|          * a list. */
 5776|         if(n_brothers + n_children == 0) {
 5777|             while(n_parents < ctx->n_containers  &&  ctx->containers[n_parents].ch != _T('>'))
 5778|                 n_parents++;
 5779|         }
 5780|     }
 5781| 
 5782|     while(TRUE) {
 5783|         /* Check whether we are fenced code continuation. */
 5784|         if(pivot_line->type == MD_LINE_FENCEDCODE) {
 5785|             line->beg = off;
 5786| 
 5787|             /* We are another MD_LINE_FENCEDCODE unless we are closing fence
 5788|              * which we transform into MD_LINE_BLANK. */
 5789|             if(line->indent < ctx->code_indent_offset) {
 5790|                 if(md_is_closing_code_fence(ctx, CH(pivot_line->beg), off, &off)) {
 5791|                     line->type = MD_LINE_BLANK;
 5792|                     ctx->last_line_has_list_loosening_effect = FALSE;
 5793|                     break;
 5794|                 }
 5795|             }
 5796| 
 5797|             /* Change indentation accordingly to the initial code fence. */
 5798|             if(n_parents == ctx->n_containers) {
 5799|                 if(line->indent > pivot_line->indent)
 5800|                     line->indent -= pivot_line->indent;
 5801|                 else
 5802|                     line->indent = 0;
 5803| 
 5804|                 line->type = MD_LINE_FENCEDCODE;
 5805|                 break;
 5806|             }
 5807|         }
 5808| 
 5809|         /* Check whether we are HTML block continuation. */
 5810|         if(pivot_line->type == MD_LINE_HTML  &&  ctx->html_block_type > 0) {
 5811|             if(n_parents < ctx->n_containers) {
 5812|                 /* HTML block is implicitly ended if the enclosing container
 5813|                  * block ends. */
 5814|                 ctx->html_block_type = 0;
 5815|             } else {
 5816|                 int html_block_type;
 5817| 
 5818|                 html_block_type = md_is_html_block_end_condition(ctx, off, &off);
 5819|                 if(html_block_type > 0) {
 5820|                     MD_ASSERT(html_block_type == ctx->html_block_type);
 5821| 
 5822|                     /* Make sure this is the last line of the block. */
 5823|                     ctx->html_block_type = 0;
 5824| 
 5825|                     /* Some end conditions serve as blank lines at the same time. */
 5826|                     if(html_block_type == 6 || html_block_type == 7) {
 5827|                         line->type = MD_LINE_BLANK;
 5828|                         line->indent = 0;
 5829|                         break;
 5830|                     }
 5831|                 }
 5832| 
 5833|                 line->type = MD_LINE_HTML;
 5834|                 n_parents = ctx->n_containers;
 5835|                 break;
 5836|             }
 5837|         }
 5838| 
 5839|         /* Check for blank line. */
 5840|         if(off >= ctx->size  ||  ISNEWLINE(off)) {
 5841|             if(pivot_line->type == MD_LINE_INDENTEDCODE  &&  n_parents == ctx->n_containers) {
 5842|                 line->type = MD_LINE_INDENTEDCODE;
 5843|                 if(line->indent > ctx->code_indent_offset)
 5844|                     line->indent -= ctx->code_indent_offset;
 5845|                 else
 5846|                     line->indent = 0;
 5847|                 ctx->last_line_has_list_loosening_effect = FALSE;
 5848|             } else {
 5849|                 line->type = MD_LINE_BLANK;
 5850|                 ctx->last_line_has_list_loosening_effect = (n_parents > 0  &&
 5851|                         n_brothers + n_children == 0  &&
 5852|                         ctx->containers[n_parents-1].ch != _T('>'));
 5853| 
 5854|     #if 1
 5855|                 /* See https://github.com/mity/md4c/issues/6
 5856|                  *
 5857|                  * This ugly checking tests we are in (yet empty) list item but
 5858|                  * not its very first line (i.e. not the line with the list
 5859|                  * item mark).
 5860|                  *
 5861|                  * If we are such a blank line, then any following non-blank
 5862|                  * line which would be part of the list item actually has to
 5863|                  * end the list because according to the specification, "a list
 5864|                  * item can begin with at most one blank line."
 5865|                  */
